1 + 19 = 63', null, 25, 'published'), ('mission-maths-2', 'maths', 'mission', 'Quick Maths', 'maths', 1, array['any','office','learning','market','food']::text[], 'Three quick sums, one per teammate. Multiply and divide before you add and subtract.', '{"scout":{"title":"Sum 1","body":"5² − 4 = ?","mono":true,"big":false},"decoder":{"title":"Sum 2","body":"(7 + 6) × 3 − 2 = ?","mono":true,"big":false},"intel":{"title":"Sum 3","body":"66 ÷ 11 + 1 = ?","mono":true,"big":false}}'::jsonb, '[{"label":"Sum 1 (Scout)","accept":["21"]},{"label":"Sum 2 (Decoder)","accept":["37"]},{"label":"Sum 3 (Intel)","accept":["7"]}]'::jsonb, false, 3, 200, 'No calculators needed — multiply first, then add or subtract.', '21: 5² − 4 = 21 | 37: (7 + 6) × 3 − 2 = 37 | 7: 66 ÷ 11 + 1 = 7', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now();
